style.css:
@-moz-document domain("pinterest.com") {
/* jasnoróżowa otoczka na hover */
  div[data-test-id="pin"]:hover {
    box-shadow: 0 0 8px #f1b9e3 !important;
    border: 1px solid #f1b9e3 !important;
  }

  /* ładniejsze przyciski zapisu */
  [data-test-id="pin-save-button"] {
    background-color: #e19dcd !important;
    color: black !important;
    border: none !important;
    border-radius: 20px !important;
    padding: 8px 12px !important;
    font-weight: 500 !important;
    font-size: 14px !important;
    transition: background-color 0.2s ease-in-out;
  }

  /* najechanie = jaśniejszy róż */
  [data-test-id="pin-save-button"]:hover {
    background-color: #f2c3e6 !important;
    color: black !important;
  }

  /* jeśli pokazuje nazwę tablicy (dynamicznie) */
  [data-test-id="pin-save-button"] span {
    color: black !important;
  }

  /* jeśli obramowanie nadal się pojawia z zewnętrznych styli */
  [data-test-id="pin-save-button"]::before,
  [data-test-id="pin-save-button"]::after {
    border: none !important;
    box-shadow: none !important;
  }
}
